const prev = $('Code in JavaScript2').first().json;

let inputItem = $input.first()?.json || {};
let raw = "";

if (typeof inputItem === 'string') {
  raw = inputItem;
} else if (inputItem.text) {
  raw = typeof inputItem.text === 'string' ? inputItem.text : JSON.stringify(inputItem.text);
} else if (inputItem.output) {
  raw = typeof inputItem.output === 'string' ? inputItem.output : JSON.stringify(inputItem.output);
} else if (inputItem.message?.content) {
  raw = typeof inputItem.message.content === 'string' ? inputItem.message.content : JSON.stringify(inputItem.message.content);
} else if (inputItem.decision || inputItem.action || inputItem.public_reply) {
  raw = JSON.stringify(inputItem);
} else {
  raw = JSON.stringify(inputItem);
}

// 1. Clean markdown blocks
raw = raw.replace(/```json/gi, "").replace(/```/g, "").trim();

// 2. Fallback DM message loaded directly from your Dashboard settings
const dashboardFallbackDm = (prev.fallback_dm_message || "").trim() || "أهلاً بحضرتك يا فندم نورتنا! 🍗 تقدر تطلب أو تستفسر عن أي حاجة من هنا مباشرة 🛵";

// 3. Extract JSON object
const match = raw.match(/\{[\s\S]*\}/);
if (!match) {
  const isDelete = raw.toUpperCase().includes("DELETE");
  return [{
    json: {
      token: prev.token,
      page_id: prev.page_id,
      post_id: prev.post_id,
      comment_id: prev.comment_id,
      commenter_id: prev.commenter_id,
      commenter_name: prev.commenter_name,
      comment_text: prev.comment_text,
      reply_delay_sec: prev.reply_delay_sec,

      decision: isDelete ? "DELETE" : "KEEP",
      action: "normal",
      is_complaint: false,
      public_reply: raw,
      send_dm: !isDelete,
      dm_message: dashboardFallbackDm
    }
  }];
}

let jsonString = match[0];

// 4. Fix unescaped newlines inside strings
let fixed = "";
let inString = false;
let escaped = false;

for (let i = 0; i < jsonString.length; i++) {
  const ch = jsonString[i];
  if (!inString) {
    fixed += ch;
    if (ch === '"') inString = true;
  } else {
    if (escaped) {
      fixed += ch;
      escaped = false;
    } else if (ch === "\\") {
      fixed += ch;
      escaped = true;
    } else if (ch === '"') {
      fixed += ch;
      inString = false;
    } else if (ch === "\n") {
      fixed += "\\n";
    } else if (ch === "\r") {
      // ignore CR
    } else {
      fixed += ch;
    }
  }
}

let parsed = {};
try {
  parsed = JSON.parse(fixed);
} catch (err) {
  try {
    parsed = JSON.parse(jsonString);
  } catch (err2) {
    parsed = {
      decision: "KEEP",
      action: "normal",
      is_complaint: false,
      public_reply: raw,
      dm_message: ""
    };
  }
}

const isKeep = parsed.decision !== "DELETE";
const action = String(parsed.action || "normal").toLowerCase().trim();

// Use AI dm_message if provided, otherwise use the dashboard fallback message
const finalDmMessage = (parsed.dm_message && parsed.dm_message.trim().length > 0)
  ? parsed.dm_message.trim()
  : dashboardFallbackDm;

return [{
  json: {
    token: prev.token,
    page_id: prev.page_id,
    post_id: prev.post_id,
    comment_id: prev.comment_id,
    commenter_id: prev.commenter_id,
    commenter_name: prev.commenter_name,
    comment_text: prev.comment_text,
    reply_delay_sec: prev.reply_delay_sec,

    // Decision & Action Fields
    decision: isKeep ? "KEEP" : "DELETE",
    action: action,
    is_complaint: Boolean(parsed.is_complaint),
    public_reply: parsed.public_reply || "",

    // Always send DM for any KEEP comment using dashboard fallback if needed
    send_dm: isKeep,
    dm_message: isKeep ? finalDmMessage : ""
  }
}];

