    attachment_url: attachmentUrl,
    text: text || payload || (isImage ? "[صورة من العميل]" : ""),
    payload: payload,
    psid,
    page_id: ch.page_id,
    channel_id: ch.id,
    token: ch.token,
    mid,
    timestamp: ev.timestamp || Date.now(),
  }
}];

